arguments.new_string:
# prune: keep=3 newest of each
for i in 3 4 5 6; do echo "r$i" > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 2026100$i; done
touch "$d/logs/app.log.9x" "$d/archive/other.20200101"
[ "$(ls "$d/logs" | grep -c '^app.log\.[0-9]*$')" = 3 ] || { echo "local count"; fail=1; }
[ ! -e "$d/logs/app.log.4" ] || { echo "local old"; fail=1; }
[ "$(cat "$d/logs/app.log.3")" = r4 ] || { echo "local newest kept"; fail=1; }
[ "$(ls "$d/archive" | grep -c '^app.log\.')" = 3 ] || { echo "archive count"; fail=1; }
{ [ ! -e "$d/archive/app.log.20261001" ] && [ -e "$d/archive/app.log.20261006" ]; } || { echo "archive order"; fail=1; }
[ -e "$d/archive/other.20200101" ] && [ -e "$d/logs/app.log.9x" ] || { echo "other names untouched"; fail=1; }
rm -rf "$d"

